    {
      "rank": 1,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Alexander Polyakov",
        "Alexander B. Zamolodchikov",
        "John Cardy"
      ],
      "assessment": {
        "nobel_worthiness": "Conformal field theory made two-dimensional critical phenomena tractable through a powerful universal framework, with lasting influence across statistical physics and quantum field theory.",
        "attribution": "Polyakov helped establish the field-theoretic approach, Zamolodchikov developed its powerful two-dimensional structure, and Cardy connected it to critical phenomena and testable predictions. The work is collaborative and spans distinct contributions.",
        "maturity": "The framework and its consequences have been tested and used for decades; its importance is exceptionally well established.",
        "uncertainties": [
          "A three-person prize would require a choice about how much of the broader development to represent."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Mehran Kardar",
        "Yi-Cheng Zhang",
        "Kazumasa A. Takeuchi"
      ],
      "assessment": {
        "nobel_worthiness": "The KPZ universality class identified a simple mechanism for scale-invariant growth far from equilibrium and has become a major organizing framework for non-equilibrium statistical physics.",
        "attribution": "Kardar and Zhang contributed to the foundational theory; Takeuchi's precise experiments helped establish the class's distinctive scaling behavior. Credit should distinguish theoretical creation from experimental confirmation.",
        "maturity": "The theory has decades of development and unusually clear experimental tests, though its reach across systems continues to grow.",
        "uncertainties": [
          "The proposed trio may not capture all foundational contributions to the original growth equation and its later development."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory supplied a broadly useful framework for understanding local correlations in strongly interacting electrons, turning difficult many-body problems into tractable self-consistent ones.",
        "attribution": "Georges and Kotliar helped develop the method and its applications; Vollhardt was central to its conceptual and theoretical development. Their complementary contributions support shared credit.",
        "maturity": "The method has been extensively tested against numerical and experimental work and remains a standard tool.",
        "uncertainties": [
          "The boundary between the original formulation and later advances makes a compact attribution difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Andrea J. Liu",
        "Corey S. O'Hern",
        "Sidney R. Nagel"
      ],
      "assessment": {
        "nobel_worthiness": "Jamming offered a unifying way to think about rigidity and arrest in disordered materials, linking phenomena that had often been treated separately.",
        "attribution": "Liu and Nagel helped frame the jamming picture, while O'Hern's work supplied influential numerical and theoretical characterization. Credit is plausible but the field developed through a broad community.",
        "maturity": "The framework has been productive for decades, but the status and universality of a single sharp transition remain debated across materials and protocols.",
        "uncertainties": [
          "It is not settled whether jamming defines one universal critical phenomenon or a family of related transitions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Rafi Bistritzer",
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed a striking route to tunable correlated quantum matter and opened an exceptionally active experimental and theoretical field.",
        "attribution": "Bistritzer and MacDonald predicted the special-angle electronic structure; Jarillo-Herrero's experiments revealed the correlated phases. The theory–experiment pairing is compelling.",
        "maturity": "The phenomenon is robust and has been studied intensively, but the microscopic interpretation of several phases and the field's long-term reach are still developing.",
        "uncertainties": [
          "The relationship between superconductivity, correlated insulating states, and the proposed underlying mechanisms remains unsettled."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Brian D. Metzger",
        "Daniel Kasen",
        "Masaomi Tanaka"
      ],
      "assessment": {
        "nobel_worthiness": "Neutron-star mergers and their kilonovae established a vivid connection between multi-messenger astronomy and the creation of heavy elements, a major advance in astrophysics.",
        "attribution": "Metzger and collaborators developed key predictions; Kasen and Tanaka contributed central models of the observable emission. The discovery and interpretation also depend on a much larger observational and theoretical community.",
        "maturity": "The merger and kilonova connection has strong observational support, though the detailed element yields and relative contributions of different sites continue to be refined.",
        "uncertainties": [
          "Credit for the discovery, predictions, observations, and nucleosynthesis interpretation is spread across many contributors."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality has profoundly shaped theoretical physics by relating gravitational theories to quantum field theories, offering a powerful conceptual and calculational framework.",
        "attribution": "Maldacena's duality proposal is the defining contribution; Witten and Polyakov made major contributions to the broader framework and its development. The credited roles are important but not identical.",
        "maturity": "The correspondence is deeply developed and useful in several settings, but it remains a theoretical framework without direct empirical confirmation as a description of our universe.",
        "uncertainties": [
          "The physical scope of the duality and its connection to observable gravity remain open.",
          "The proposed shared credit risks obscuring Maldacena's distinct role in the central conjecture."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Controlled atoms made quantum simulation and information processing experimentally concrete, enabling direct study of many-body phenomena with unprecedented control.",
        "attribution": "Cirac and Zoller developed influential theoretical proposals, while Bloch helped realize and advance the experimental platform. Blatt also has a strong claim within the broader development represented by this candidate.",
        "maturity": "The experimental methods and scientific results are substantial, but the platform's ultimate reach and durable impact are still unfolding.",
        "uncertainties": [
          "The candidate groups several related advances, making it difficult to identify a single prize-sized contribution and a complete set of recipients."
        ]
      }
    }
  ]
